function baseChart(){const c=palette();return {responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{backgroundColor:c.ink,titleColor:c.bg,bodyColor:c.bg,padding:11,displayColors:false,titleFont:{size:11},bodyFont:{size:11}}},scales:{x:{grid:{display:false},border:{color:c.line},ticks:{color:c.muted,font:{size:10},maxTicksLimit:7}},y:{grid:{color:c.line,drawTicks:false},border:{display:false},ticks:{color:c.muted,font:{size:10},padding:8,callback:v=>fmtGBP.format(v/100)}}}}}
